import{_ as a}from"./chunks/infuse-files-favorites.ZRmFSxjS.js";import{_ as s}from"./chunks/infuse-custom-catalog-items.CH7-HJyD.js";import{_ as o,o as t,c as n,a2 as r}from"./chunks/framework.lxr64Vqo.js";const v=JSON.parse('{"title":"Release v1.4.325","description":"","frontmatter":{},"headers":[],"relativePath":"updates/v1-4-325.md","filePath":"updates/v1-4-325.md","lastUpdated":1795112636000}'),i={name:"updates/v1-4-325.md"};function l(d,e,u,c,h,m){return t(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="release-v1-4-325" tabindex="-1">Release v1.4.325 <a class="header-anchor" href="#release-v1-4-325" aria-label="Permalink to &quot;Release v1.4.325&quot;">​</a></h1><div style="margin-bottom:1.5rem;"><span class="badge-pill badge-feature">Feature</span><span class="badge-pill badge-perf">Performance</span><span style="color:#71717a;font-size:0.85rem;margin-left:8px;">Released on November 19, 2026</span></div><h2 id="🍎-infuse-custom-catalogs-shelves" tabindex="-1">🍎 Infuse Custom Catalogs &amp; Shelves <a class="header-anchor" href="#🍎-infuse-custom-catalogs-shelves" aria-label="Permalink to &quot;🍎 Infuse Custom Catalogs &amp; Shelves&quot;">​</a></h2><p>In this release, we&#39;ve brought full support for <strong>Custom AI Shelves directly inside Infuse</strong>!</p><p>Previously, Infuse users could only browse the default &quot;Movies&quot;, &quot;TV Shows&quot;, and &quot;Anime&quot; virtual folders. With v1.4.325, any custom catalog you create inside NoxMedia (such as <em>Murder Mystery Dark</em>, <em>Marvel Universe</em>, or <em>Retro Sci-Fi</em>) is dynamically exposed in the Jellyfin Bridge when Infuse connects.</p><div class="screenshot-frame"><img src="'+a+'" alt="Infuse Files showing NoxMedia Custom Catalogs"><div class="screenshot-caption">Custom shelves like &quot;Murder Mystery Dark&quot; appear alongside default libraries in Infuse Files.</div></div><h3 id="⭐-pinned-favorites-on-apple-tv-ios" tabindex="-1">⭐ Pinned Favorites on Apple TV &amp; iOS <a class="header-anchor" href="#⭐-pinned-favorites-on-apple-tv-ios" aria-label="Permalink to &quot;⭐ Pinned Favorites on Apple TV &amp; iOS&quot;">​</a></h3><p>You can now tap the <strong>Star</strong> icon on any custom shelf to pin it as a Home screen Favorite in Infuse. It will render as a dedicated horizontal carousel on your Apple TV or iPhone/iPad!</p><div class="screenshot-frame"><img src="'+s+'" alt="Infuse Custom Shelf Items Loaded with Posters"><div class="screenshot-caption">Loaded items with instant high-resolution posters and metadata.</div></div><hr><h2 id="⚡-0ms-instant-catalog-caching" tabindex="-1">⚡ 0ms Instant Catalog Caching <a class="header-anchor" href="#⚡-0ms-instant-catalog-caching" aria-label="Permalink to &quot;⚡ 0ms Instant Catalog Caching&quot;">​</a></h2><h3 id="the-problem" tabindex="-1">The Problem <a class="header-anchor" href="#the-problem" aria-label="Permalink to &quot;The Problem&quot;">​</a></h3><p>When Infuse opens a custom folder, it queries all items in that collection simultaneously. In earlier versions, this required parsing thousands of raw Telegram messages on the fly and doing synchronous HTTP network queries to resolve runtimes, resulting in a 1–2 minute delay.</p><h3 id="the-solution" tabindex="-1">The Solution <a class="header-anchor" href="#the-solution" aria-label="Permalink to &quot;The Solution&quot;">​</a></h3><ul><li><strong>Precomputed In-Memory Cache</strong>: Media groups and catalog filters are precomputed in the background and stored in high-speed RAM and disk cache (<code>media_groups_cache.json</code>).</li><li><strong>Zero-Block HTTP Calls</strong>: Removed synchronous network lookups in <code>resolveRuntimeSeconds</code>, relying on pre-cached TMDB metadata and Telegram duration attributes.</li><li><strong>Results</strong>: Loading a custom shelf with hundreds of movies/episodes in Infuse now takes <strong>0ms (instant)</strong>!</li></ul>',15)])])}const _=o(i,[["render",l]]);export{v as __pageData,_ as default};
